//! The cloud folder of 1.3.1, byte for byte (design 7.1; addendum A1.2).
//!
//! The fixtures under `tests/fixtures/` are what 1.3.1 itself wrote, generated by C0 from the 1.3.1 code on a fixed
//! clock; nothing here changes them. R0 says what they cover, R1 reads and writes back every file in them, and R2-R4
//! start Studio Mac on this version from its 1.3.1 store and its folder, then check that it writes exactly what 1.3.1
//! wrote there, and nothing else. They hold unchanged once stamps follow the hybrid clock (I2): with converged data
//! `reconcile` writes no stamp.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, MutexGuard, PoisonError};
use std::time::{Duration, SystemTime};

use serde_json::Value;

use crate::backup::LEGACY_COPY;
use crate::gz;
use crate::lease::{LeaseRecord, LeaseRecordState};
use crate::merge::merge;
use crate::model::{DeviceFile, LocalFile, Shared};
use crate::persist::MAIN_FILE;
use crate::service::Service;
use crate::store::{DB_FILE, record_rows};
use crate::sync::{MAX_REMOTE_FILE_BYTES, RealIo, SyncIo, run_cycle_within};
use crate::time::{Clock, ManualClock};

/// Where the fixtures' folder was connected, as Studio Mac's store names it.
const VIRTUAL_ROOT: &str = "/cloud/OneDrive";
const FOLDERS: [&str; 2] = ["cloud-1.3.1", "cloud-1.3.1-epoch"];
/// Studio Mac, this device.
const OWN: &str = "aaaaaaaa-1111-4111-8111-111111111111";
/// Office PC.
const OTHER: &str = "bbbbbbbb-2222-4222-8222-222222222222";
/// Studio Mac's last write in `cloud-1.3.1/` (its README).
const LAST_WRITE: &str = "2026-10-08T09:58:00Z";
const LIMIT: Duration = Duration::from_secs(20);

/// Fields no record in the fixtures sets, as no step of the story 1.3.1 was run through needs them: a task continued
/// from another, a rounding rule for one project, and an end settled by another device. Their round trip rests on the
/// same derive as every other field's. Pinned, so a change to the fixtures in either direction shows here.
const NEVER_SET: [&str; 3] = [
    "rounding.projectId",
    "segments.edit.settled",
    "tasks.continuedFrom",
];

fn fixture(rel: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(rel)
}

fn lock(m: &Mutex<Service>) -> MutexGuard<'_, Service> {
    m.lock().unwrap_or_else(PoisonError::into_inner)
}

/// Every file under `root`, by its path relative to it.
fn files_under(root: &Path) -> BTreeMap<PathBuf, Vec<u8>> {
    fn walk(root: &Path, dir: &Path, out: &mut BTreeMap<PathBuf, Vec<u8>>) {
        for entry in fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if entry.file_type().unwrap().is_dir() {
                walk(root, &path, out);
            } else {
                let rel = path.strip_prefix(root).unwrap().to_path_buf();
                out.insert(rel, fs::read(&path).unwrap());
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(root, root, &mut out);
    out
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for entry in fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let dest = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_tree(&entry.path(), &dest);
        } else {
            fs::copy(entry.path(), &dest).unwrap();
        }
    }
}

fn device_path(folder: &Path, id: &str) -> PathBuf {
    folder.join(format!("zWorkTracker/devices/{id}.json"))
}

fn read_device(folder: &Path, id: &str) -> (DeviceFile, Vec<u8>) {
    let bytes = fs::read(device_path(folder, id)).unwrap();
    (serde_json::from_slice(&bytes).unwrap(), bytes)
}

/// The folder the fixtures were captured in, mapped onto a copy of them, so Studio Mac's 1.3.1 store is used as it is,
/// `syncTargets` and all. C0's `FolderIo` did the same to write them.
#[derive(Clone)]
struct MappedIo {
    virtual_root: PathBuf,
    real: PathBuf,
}

impl MappedIo {
    fn map(&self, path: &Path) -> io::Result<PathBuf> {
        let rest = path
            .strip_prefix(&self.virtual_root)
            .map_err(|_| io::Error::new(io::ErrorKind::NotFound, "outside the cloud folder"))?;
        Ok(self.real.join(rest))
    }
}

impl SyncIo for MappedIo {
    fn is_dir(&self, path: &Path) -> bool {
        self.map(path).is_ok_and(|p| RealIo.is_dir(&p))
    }
    fn create_dir_all(&self, path: &Path) -> io::Result<()> {
        RealIo.create_dir_all(&self.map(path)?)
    }
    fn list(&self, path: &Path) -> io::Result<Vec<String>> {
        let mut names = RealIo.list(&self.map(path)?)?;
        names.sort();
        Ok(names)
    }
    fn file_size(&self, path: &Path) -> io::Result<u64> {
        RealIo.file_size(&self.map(path)?)
    }
    fn read(&self, path: &Path, max: u64) -> io::Result<Vec<u8>> {
        RealIo.read(&self.map(path)?, max)
    }
    fn write_atomic(&self, dest: &Path, tmp: &Path, bytes: &[u8]) -> io::Result<()> {
        RealIo.write_atomic(&self.map(dest)?, &self.map(tmp)?, bytes)
    }
    fn sleep(&self, _d: Duration) {}
    fn remove_file(&self, path: &Path) -> io::Result<()> {
        RealIo.remove_file(&self.map(path)?)
    }
}

/// Each field that is null in one record and set in none, with the fields left out when not set that no record has.
fn fields_never_set(files: &[Value]) -> BTreeSet<String> {
    let mut null = BTreeSet::new();
    let mut set = BTreeSet::new();
    let mut skipped_seen = BTreeSet::new();
    for file in files {
        for (kind, records) in file["data"].as_object().unwrap() {
            for record in records.as_object().unwrap().values() {
                for (field, value) in record.as_object().unwrap() {
                    let name = format!("{kind}.{field}");
                    if value.is_null() {
                        null.insert(name);
                    } else {
                        set.insert(name);
                    }
                }
                if record["edit"].get("settled").is_some() {
                    skipped_seen.insert("segments.edit.settled".to_owned());
                }
            }
        }
        if file.get("epochInfo").is_some() {
            skipped_seen.insert("epochInfo".to_owned());
        }
    }
    // Left out of the JSON when not set (`skip_serializing_if`), so absence is all a reader sees.
    let skipped = [
        "projects.identityStamp",
        "projects.billingStamp",
        "projects.budgetStamp",
        "projects.archiveStamp",
        "segments.edit.settled",
        "epochInfo",
    ];
    let mut never: BTreeSet<String> = null.difference(&set).cloned().collect();
    for field in skipped {
        if !set.contains(field) && !skipped_seen.contains(field) {
            never.insert(field.to_owned());
        }
    }
    never
}

/// R0 (addendum A1.2).
#[test]
fn fixtures_cover_every_kind_and_optional_field() {
    let mut files = Vec::new();
    for folder in FOLDERS {
        for id in [OWN, OTHER] {
            let bytes = fs::read(device_path(&fixture(folder), id)).unwrap();
            files.push(serde_json::from_slice::<Value>(&bytes).unwrap());
        }
    }
    let kinds = serde_json::to_value(Shared::default()).unwrap();
    let kinds: Vec<&String> = kinds.as_object().unwrap().keys().collect();
    assert_eq!(kinds.len(), 15);
    for kind in kinds {
        assert!(
            files
                .iter()
                .any(|f| f["data"][kind].as_object().is_some_and(|m| !m.is_empty())),
            "no record of {kind}"
        );
    }
    let never: Vec<String> = fields_never_set(&files).into_iter().collect();
    assert_eq!(never, NEVER_SET);

    // What A1.2 asked of Office PC's file.
    let (b, _) = read_device(&fixture("cloud-1.3.1"), OTHER);
    assert!(!b.data.pause_requests.is_empty(), "a pause request");
    assert!(
        b.data.segments.values().any(|s| s.end.is_none()),
        "an open segment"
    );
    assert!(b.data.tasks.values().any(|t| t.deleted), "a deleted task");
    assert!(
        b.data.projects.values().any(|p| p.archived),
        "an archived project"
    );
    assert!(
        b.data.segments.values().any(|s| s.edit.is_some()),
        "a corrected segment"
    );
    for id in [OWN, OTHER] {
        let (file, _) = read_device(&fixture("cloud-1.3.1-epoch"), id);
        assert_eq!(file.epoch_info.map(|e| e.epoch), Some(1), "after a restore");
    }
    let states: BTreeSet<String> = [OWN, OTHER]
        .iter()
        .map(|id| {
            let path = fixture("cloud-1.3.1").join(format!("zWorkTracker/lease/{id}.json"));
            let record: LeaseRecord = serde_json::from_slice(&fs::read(path).unwrap()).unwrap();
            format!("{:?}", record.state)
        })
        .collect();
    assert_eq!(
        states,
        BTreeSet::from([
            format!("{:?}", LeaseRecordState::Held),
            format!("{:?}", LeaseRecordState::Released)
        ])
    );
}

/// R1.
#[test]
fn every_cloud_file_reads_and_writes_back_byte_for_byte() {
    let max = usize::try_from(MAX_REMOTE_FILE_BYTES).unwrap();
    for folder in FOLDERS {
        let mut count: BTreeMap<&str, usize> = BTreeMap::new();
        for (rel, bytes) in files_under(&fixture(folder).join("zWorkTracker")) {
            let name = rel.to_string_lossy().replace('\\', "/");
            let what = format!("{folder}/zWorkTracker/{name}");
            let kind = if name.starts_with("devices/") {
                let file: DeviceFile = serde_json::from_slice(&bytes).unwrap();
                assert_eq!(serde_json::to_vec(&file).unwrap(), bytes, "{what}");
                "devices"
            } else if name.starts_with("lease/") {
                let record: LeaseRecord = serde_json::from_slice(&bytes).unwrap();
                assert_eq!(serde_json::to_vec(&record).unwrap(), bytes, "{what}");
                "lease"
            } else if name.starts_with("versions/") && name.ends_with(".json.gz") {
                let json = gz::decompress(&bytes, max).unwrap();
                let file: DeviceFile = serde_json::from_slice(&json).unwrap();
                assert_eq!(serde_json::to_vec(&file).unwrap(), json, "{what}, unpacked");
                // The packed bytes come from miniz_oxide, so they hold while it stays at its Cargo.lock version.
                assert_eq!(gz::compress(&json), bytes, "{what}, packed");
                "versions"
            } else if name.starts_with("versions/") && name.ends_with(".changes.txt") {
                // Text 1.3.1 wrote, naming "(app 1.3.1)": only R4 holds it, unchanged.
                "changes"
            } else {
                panic!("a file the fixtures shouldn't hold: {what}");
            };
            *count.entry(kind).or_default() += 1;
        }
        let versions = if folder == "cloud-1.3.1" { 3 } else { 6 };
        assert_eq!(
            count,
            BTreeMap::from([
                ("changes", versions),
                ("devices", 2),
                ("lease", 2),
                ("versions", versions)
            ]),
            "{folder}"
        );
    }
}

/// Studio Mac's first start on this version, from its 1.3.1 store and the folder as 1.3.1 left them, at the moment of
/// its last write there, and one sync.
struct Bootstrapped {
    dir: tempfile::TempDir,
    cloud: tempfile::TempDir,
    clock: ManualClock,
    svc: Mutex<Service>,
    own: DeviceFile,
    own_bytes: Vec<u8>,
    legacy_modified: SystemTime,
}

fn bootstrap() -> Bootstrapped {
    let folder = fixture("cloud-1.3.1");
    let (own, own_bytes) = read_device(&folder, OWN);
    let (other, _) = read_device(&folder, OTHER);
    // What R2 rests on. A failure here is a fixture that no longer says what its README says.
    assert_eq!(
        merge(&own.data, &other.data),
        own.data,
        "bad fixture: Office PC's file holds what Studio Mac's doesn't"
    );
    assert!(
        own.data
            .segments
            .values()
            .filter(|s| s.device_id == OWN)
            .all(|s| s.end.is_some()),
        "bad fixture: a segment of Studio Mac is open in its own file"
    );
    assert!(
        own.epoch_info.is_none(),
        "bad fixture: Studio Mac's file follows a restore"
    );
    assert_eq!(own.written_at.iso(), LAST_WRITE, "bad fixture: last write");
    let local: LocalFile =
        serde_json::from_slice(&fs::read(fixture("cloud-1.3.1.local.json")).unwrap()).unwrap();
    assert_eq!(
        local.device_id, OWN,
        "bad fixture: the store is Studio Mac's"
    );
    assert_eq!(
        local.data, own.data,
        "bad fixture: its store and its file differ"
    );
    assert_eq!(
        local
            .prefs
            .sync_targets
            .iter()
            .map(|t| t.root.as_str())
            .collect::<Vec<_>>(),
        [VIRTUAL_ROOT],
        "bad fixture: the store's folder"
    );

    let dir = tempfile::tempdir().unwrap();
    let legacy = dir.path().join(MAIN_FILE);
    fs::copy(fixture("cloud-1.3.1.local.json"), &legacy).unwrap();
    let legacy_modified = fs::metadata(&legacy).unwrap().modified().unwrap();
    let cloud = tempfile::tempdir().unwrap();
    copy_tree(&folder, cloud.path());
    let clock = ManualClock::at(LAST_WRITE);
    let svc = Service::open(dir.path(), Arc::new(clock.clone()), "Studio Mac").unwrap();
    assert!(
        svc.awaiting_cloud(),
        "case C: the data is to come from the folder"
    );
    let svc = Mutex::new(svc);
    let io = MappedIo {
        virtual_root: PathBuf::from(VIRTUAL_ROOT),
        real: cloud.path().to_path_buf(),
    };
    assert!(run_cycle_within(&svc, &io, LIMIT));
    {
        let mut s = lock(&svc);
        assert!(!s.awaiting_cloud());
        let status = s.target_status_mut(VIRTUAL_ROOT).clone();
        assert_eq!(status.last_error, None);
        assert_eq!(
            status.last_written_at,
            Some(clock.now()),
            "its file was written"
        );
    }
    Bootstrapped {
        dir,
        cloud,
        clock,
        svc,
        own,
        own_bytes,
        legacy_modified,
    }
}

/// R2.
#[test]
fn a_bootstrapped_store_writes_this_devices_file_byte_for_byte() {
    let run = bootstrap();
    assert_eq!(
        fs::read(device_path(run.cloud.path(), OWN)).unwrap(),
        run.own_bytes
    );
    let s = lock(&run.svc);
    assert_eq!(s.file().data, run.own.data);
    assert_eq!(s.file().last_heartbeat, run.own.last_heartbeat);
}

/// R3.
#[test]
fn the_store_returns_every_record_as_it_was_written() {
    let run = bootstrap();
    drop(run.svc);
    let svc = Service::open(run.dir.path(), Arc::new(run.clock.clone()), "Studio Mac").unwrap();
    assert_eq!(
        serde_json::to_vec(&svc.device_file()).unwrap(),
        run.own_bytes
    );
    assert_eq!(svc.stored().data, run.own.data);
    let mut expected = record_rows(&run.own.data).unwrap();
    expected.sort();
    assert_eq!(
        svc.stored_rows(),
        expected,
        "every row is the record as 1.3.1 wrote it"
    );
}

/// R4.
#[test]
fn nothing_else_in_the_folder_or_the_legacy_file_changes() {
    let run = bootstrap();
    let mut before = files_under(&fixture("cloud-1.3.1"));
    let mut after = files_under(run.cloud.path());
    let own = PathBuf::from(format!("zWorkTracker/devices/{OWN}.json"));
    assert!(before.remove(&own).is_some() && after.remove(&own).is_some());
    assert_eq!(
        after.keys().collect::<Vec<_>>(),
        before.keys().collect::<Vec<_>>()
    );
    for (rel, bytes) in &before {
        assert!(after[rel] == *bytes, "{} changed", rel.display());
    }

    let dir = run.dir.path();
    let legacy = dir.join(MAIN_FILE);
    assert_eq!(
        fs::read(&legacy).unwrap(),
        fs::read(fixture("cloud-1.3.1.local.json")).unwrap()
    );
    assert_eq!(
        fs::metadata(&legacy).unwrap().modified().unwrap(),
        run.legacy_modified
    );
    for name in [
        "z-work-data.json.bak",
        "z-work-data.json.tmp",
        "z-work-heartbeat.json",
    ] {
        assert!(!dir.join(name).exists(), "{name}");
    }
    assert!(dir.join(DB_FILE).is_file());
    assert_eq!(
        fs::read(dir.join("backups").join(LEGACY_COPY)).unwrap(),
        fs::read(&legacy).unwrap(),
        "A1.1: the old store, in Settings > Backups"
    );
}
